(async () => {
  const res = {steps: []};
  try {
    const m = await import('/assets/js/wg/main.js?x=' + Date.now());
    res.steps.push('import ok: ' + Object.keys(m).join(','));
    const root = document.querySelector('[data-window-gallery]');
    root.classList.remove('is-failed');
    m.mount(root);
    await new Promise(r => setTimeout(r, 3000));
    res.canvas = !!root.querySelector('canvas');
    res.swatches = root.querySelectorAll('.wg__swatch').length;
    res.cls = root.className;
  } catch (e) {
    res.steps.push('error: ' + (e && e.name) + ' ' + String(e && e.message).slice(0, 200));
  }
  return res;
})()
